package com.example

/**
 * Curated, 100% syllabus-accurate, non-repeating Flashcard Data
 * for Science (විද්‍යාව) and Mathematics (ගණිතය) across 15 distinct sets (20 cards per set = 300 cards).
 */
object FlashcardSetsScienceMaths {

  fun getScienceCard(setNum: Int, cardNum: Int, grade: String, theme: String): CardContentTuple {
    // 15 sets for Science covering the whole syllabus
    return when (setNum) {
      1 -> getScienceSet1(cardNum) // ජීවයේ රසායනික පදනම (Biomolecules)
      2 -> getScienceSet2(cardNum) // පදාර්ථයේ ව්‍යුහය & ආවර්තිතා වගුව
      3 -> getScienceSet3(cardNum) // සෛලය & පටක (Cell & Tissues)
      4 -> getScienceSet4(cardNum) // චලිතය, නිව්ටන් නියම & බලය
      5 -> getScienceSet5(cardNum) // පීඩනය & ඝනත්වය (Pressure & Density)
      6 -> getScienceSet6(cardNum) // රසායනික බන්ධන & සංයෝග
      7 -> getScienceSet7(cardNum) // මිනිසාගේ ආහාර ජීර්ණය & පෝෂණය
      8 -> getScienceSet8(cardNum) // ප්‍රභාසංස්ලේෂණය & ශ්වසනය
      9 -> getScienceSet9(cardNum) // ධාරා විද්‍යුතය & ඕම් නියමය
      10 -> getScienceSet10(cardNum) // රසායනික ගණනය & මවුලය
      11 -> getScienceSet11(cardNum) // ආලෝකය, පරාවර්තනය & කාච
      12 -> getScienceSet12(cardNum) // තාපය, උෂ්ණත්වය & ප්‍රසාරණය
      13 -> getScienceSet13(cardNum) // ප්‍රවේණිය, DNA & මෙන්ඩල් නියම
      14 -> getScienceSet14(cardNum) // විද්‍යුත් චුම්භකත්වය & ඉලෙක්ට්‍රොනික්ස්
      15 -> getScienceSet15(cardNum) // පරිසර පද්ධති & ලෝහ නිස්සාරණය
      else -> getScienceSet1(cardNum)
    }
  }

  fun getMathCard(setNum: Int, cardNum: Int, grade: String, theme: String): CardContentTuple {
    // 15 sets for Mathematics covering the whole syllabus
    return when (setNum) {
      1 -> getMathSet1(cardNum) // වීජීය ප්‍රකාශන, සාධක & සුළු කිරීම්
      2 -> getMathSet2(cardNum) // වර්ගජ සමීකරණ & සූත්‍ර ක්‍රමය
      3 -> getMathSet3(cardNum) // සමාන්තර ශ්‍රේඪි (Arithmetic Progressions)
      4 -> getMathSet4(cardNum) // ගුණෝත්තර ශ්‍රේඪි (Geometric Progressions)
      5 -> getMathSet5(cardNum) // පයිතගරස් ප්‍රමේයය & ත්‍රිකෝණමිතිය (Sin, Cos, Tan)
      6 -> getMathSet6(cardNum) // පරිමිතිය & වර්ගඵලය (තල රූප, චාප, කේන්ද්‍රික ඛණ්ඩ)
      7 -> getMathSet7(cardNum) // පරිමාව & පෘෂ්ඨ වර්ගඵලය (සිලින්ඩර, කේතු, ගෝල)
      8 -> getMathSet8(cardNum) // ලඝුගණක & දර්ශක නීති
      9 -> getMathSet9(cardNum) // සමගාමී සමීකරණ & අසමානතා
      10 -> getMathSet10(cardNum) // වෘත්ත ජ්‍යා ප්‍රමේයයන්
      11 -> getMathSet11(cardNum) // වෘත්ත කෝණ & ස්පර්ශක ප්‍රමේයයන්
      12 -> getMathSet12(cardNum) // සම්භාවිතාව & ගස් සටහන්
      13 -> getMathSet13(cardNum) // සංඛ්‍යානය, මධ්‍යන්‍යය, මාතය & සමුච්චිත සංඛ්‍යාතය
      14 -> getMathSet14(cardNum) // වාණිජ ගණිතය (පොලිය, තීරුබදු, කොටස් වෙළඳපොළ)
      15 -> getMathSet15(cardNum) // න්‍යාස (Matrices) & කුලක (Sets)
      else -> getMathSet1(cardNum)
    }
  }

  // --- SCIENCE SET 1: ජීවයේ රසායනික පදනම ---
  private fun getScienceSet1(c: Int): CardContentTuple {
    val items = listOf(
      CardContentTuple("කාබෝහයිඩ්‍රේටවල මූලද්‍රව්‍ය සංයුතිය සහ අනුපාතය කුමක්ද?", "කාබන් (C), හයිඩ්‍රජන් (H) සහ ඔක්සිජන් (O). H:O අනුපාතය 2:1 වේ.", "ග්ලූකෝස් සූත්‍රය C₆H₁₂O₆ වේ.", "C : H : O = 1 : 2 : 1"),
      CardContentTuple("ප්‍රෝටීනවල තැනුම් ඒකකය සහ බන්ධනය කුමක්ද?", "ඇමයිනෝ අම්ල. ඒවා පෙප්ටයිඩ බන්ධන (Peptide bonds) මගින් බැඳේ.", "C, H, O, N අනිවාර්යයෙන් ද බොහෝවිට S ද අඩංගු වේ.", "ඇමයිනෝ අම්ල 20ක් ඇත"),
      CardContentTuple("ග්ලූකෝස් හඳුනාගැනීමේ පරීක්ෂාව සහ නිරීක්ෂණය කුමක්ද?", "බෙනඩික්ට් පරීක්ෂාව. රත් කළ විට නිල් පැහැයේ සිට ගඩොල් රතු අවක්ෂේපයක් ලැබේ.", "සුක්‍රෝස් ඔක්සිහාරක නොවන සීනි බැවින් සෘජුවම රතු පැහැ නොදෙයි.", "ගඩොල් රතු අවක්ෂේපය"),
      CardContentTuple("පිෂ්ටය හඳුනාගැනීමේ පරීක්ෂාව කුමක්ද?", "අයඩින් පරීක්ෂාව. දුඹුරු පැහැ අයඩින් ද්‍රාවණය තද නිල්/කළු පැහැයට හැරේ.", "අල, බත්, පාන් ආදියෙහි පිෂ්ටය බහුලව පවතී.", "අයඩින් → තද නිල්"),
      CardContentTuple("ප්‍රෝටීන හඳුනාගැනීමේ පරීක්ෂාව කුමක්ද?", "බයියුරෙට් පරීක්ෂාව. NaOH සහ CuSO₄ දැමූ විට දම්/රෝස පැහැයක් ලැබේ.", "බිත්තර සුදුමදය හෝ සෝයා කිරි පරීක්ෂාවට යොදයි.", "බයියුරෙට් → දම් පැහැය"),
      CardContentTuple("ලිපිඩ හඳුනාගැනීමේ පරීක්ෂණ 2 කුමක්ද?", "1. සුඩාන් III (රතු තට්ටුවක් වෙන්වීම) 2. සුදු කඩදාසි පරීක්ෂාව (පාරභාසක පැල්ලම).", "ලිපිඩ ජලයේ අද්‍රාව්‍ය වන අතර කාබනික ද්‍රාවකවල ද්‍රාව්‍ය වේ.", "ට්‍රයිග්ලිසරයිඩ = ග්ලිසරෝල් + මේද අම්ල 3"),
      CardContentTuple("විටමින් C ඌනතා රෝගය කුමක්ද?", "ස්කර්වි (Scurvy) රෝගය. විදුරුමහෙන් ලේ ගැලීම සහ තුවාල සුවවීම ප්‍රමාද වීම.", "දෙහි, දොඩම්, නෙල්ලි සහ පේර විටමින් C බහුල ප්‍රභව වේ.", "ඇස්කෝබික් අම්ලය"),
      CardContentTuple("විටමින් A ඌනතා රෝගය කුමක්ද?", "රාත්‍රී අන්ධතාවය (Night blindness) සහ සෙරොෆ්තැල්මියාව.", "කැරට්, කහ පැහැති පලතුරු සහ පීකුදු විටමින් A බහුලයි.", "රෙටිනෝල්"),
      CardContentTuple("විටමින් D සහ Ca ඌනතාවයෙන් වැළඳෙන රෝග මොනවාද?", "ළමුන්ට රිකට්සියාව ද, වැඩිහිටියන්ට ඔස්ටියෝමලේෂියාව සහ ඔස්ටියෝපොරෝසිස් ද වැළඳේ.", "හිරු එළිය මගින් සම තුළ විටමින් D සංස්ලේෂණය වේ.", "අස්ථි හා දත් වර්ධනය"),
      CardContentTuple("යකඩ (Fe) ඌනතාවයෙන් වැළඳෙන රෝගය කුමක්ද?", "රක්තහීනතාවය (Anaemia). හිමොග්ලොබින් මට්ටම අඩුවීමෙන් තෙහෙට්ටුව ඇතිවේ.", "පීකුදු, නිවිති සහ තද කොළ එළවළු යකඩ බහුලයි.", "හිමොග්ලොබින්හි Fe අඩංගුයි"),
      CardContentTuple("අයඩින් (I) ඌනතා රෝගය කුමක්ද?", "ගලගණ්ඩය (Goitre) සහ ළමුන්ගේ ක්‍රෙටිනිස්මය (මිටි බව හා බුද්ධි ඌනතාව).", "අයඩීකෘත ලුණු සහ මුහුදු ආහාර මගින් වළක්වාගත හැක.", "තයිරොක්සින් හෝමෝනය"),
      CardContentTuple("ජලයේ ඉහළ විශිෂ්ට තාප ධාරිතාවේ වැදගත්කම කුමක්ද?", "ජීවී සිරුරේ උෂ්ණත්වය එකවර ක්ෂණිකව වෙනස් නොවී නියතව තබාගැනීමට උපකාරී වීම.", "ජලයේ විශිෂ්ට තාප ධාරිතාව 4200 J kg⁻¹ K⁻¹ කි.", "තාප ස්වාරක්ෂකයක් වේ"),
