  // --- SCIENCE SET 4: චලිතය, නිව්ටන් නියම & බලය ---
  private fun getScienceSet4(c: Int): CardContentTuple {
    val items = listOf(
      CardContentTuple("දුර සහ විස්ථාපනය අතර වෙනස කුමක්ද?", "දුර = ගමන් කළ මුළු මාර්ග දිගයි (අදිශ). විස්ථාපනය = ආරම්භක ලක්ෂ්‍යයේ සිට සෘජු දුර සහ දිශාවයි (සදිශ).", "ඒකකය මීටර් (m) වේ.", "දුර (අදිශ) vs විස්ථාපනය (සදිශ)"),
